verus! {

enum Region {
    Border,
    RegionA,
    RegionB,
}

fn region_of(x: i8, y: i8) -> Region {
    if x > y {
        Region::RegionA
    } else if y > x {
        Region::RegionB
    } else {
        Region::Border
    }
}

fn solve(n: i8, s: Vec<char>) -> i8
    requires n >= 0 && s.len() == (n as usize)
    requires forall|i: usize| i < s.len() ==> (s[i] == 'U' || s[i] == 'R')
    ensures |result: i8| result >= 0 && result <= n
{
    let mut x: i8 = 0;
    let mut y: i8 = 0;

    // last_region remembers the last region visited that is either A or B
    // initially on border, so None means we never left the border to any region yet
    let mut last_region: Option<Region> = None;
    let mut transitions: i8 = 0;

    // Loop over moves, update position and count transitions
    let mut i: usize = 0;
    while i < s.len()
        invariant i as i8 <= n
        invariant x >= 0 && y >= 0
        invariant last_region.is_some() ==> (
            match last_region.as_ref().unwrap() {
                Region::RegionA => x > y,
                Region::RegionB => y > x,
                Region::Border => false,
            }
        )
        invariant transitions >= 0 && transitions <= i as i8 && transitions <= n
        decreases n - (i as i8)
    {
        let mv = s[i];
        if mv == 'U' {
            y += 1;
        } else {
            // mv == 'R'
            x += 1;
        }

        let current_region = region_of(x, y);

        match current_region {
            Region::Border => {
                // On border, no new region to update,
                // but last_region remains the same (per problem statement:
                // time spent on border doesn't count transitions and we compare
                // region transitions out of border against last visited region)
            }
            Region::RegionA | Region::RegionB => {
                // When we move into a non-border region:
                // Count transition if last_region is Some and different from current
                // The initial move from border to a region (last_region is None) does not count
                match &last_region {
                    None => {
                        last_region = Some(current_region);
                    }
                    Some(prev) => {
                        if *prev != current_region {
                            transitions += 1;
                        }
                        last_region = Some(current_region);
                    }
                }
            }
        }

        i += 1;
    }

    transitions
}

}